def show(r, n=4, clen=600):
    if isinstance(r, list):
        for item in r[:n]:
            if isinstance(item, dict):
                print("-", item.get("title"), "|", item.get("url"), "|", (item.get("content") or "")[:clen].replace("\n"," "))
            else:
                print("-", str(item)[:clen])
    else:
        print(str(r)[:1000])

